// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function testFuzz_property(uint64 _number, uint64 _timestamp, uint256 _basefee, uint64 _seq, uint256 _overhead, uint256 _scalar) public {
        bytes32 _hash = keccak256(abi.encode("h", _number));
        bytes32 _batcher = keccak256(abi.encode("b", _seq));
        // make the block timestamp differ from the supplied timestamp for some inputs
        vm.warp(uint256(_timestamp) + 1000 > type(uint64).max ? 1 : (uint256(_timestamp) + 1000));
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _seq, _batcher, _overhead, _scalar);
        assertTrue(c.timestamp() == _timestamp, "stored timestamp must equal supplied _timestamp");
    }
}
